            </v-row>

            <v-divider class="my-2" v-if="recommendation.description"></v-divider>

            <v-row dense v-if="recommendation.description">
              <v-col cols="12">
                <div class="trv-label mb-2">TRAINING DETAILS</div>
                <v-card outlined class="pa-3">
