                    {{ recommendation.description }}
                  </p>
                </v-card>
              </v-col>
            </v-row>
          </v-card-text>
        </v-card>

        <!-- ── Department Nomination ───────────────────────────────────── -->
        <v-card id="section-nomination" outlined class="trv-card mb-5">
          <v-card-title
            class="primary darken-1 white--text text-uppercase font-weight-bold d-flex align-center py-3"
