            <v-icon left color="white">mdi-account-group-outline</v-icon>
            Department Nomination
          </v-card-title>
          <v-card-text class="pa-4">
            <v-row dense class="mb-3">
              <v-col cols="12" md="4">
                <div class="trv-label">DEPARTMENT</div>
                <div class="text-body-1 font-weight-medium">
                  <v-icon small color="primary">mdi-office-building</v-icon>
