<script>
const RESPONSE_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/training-recommendation-response-profile";
const REVIEW_PROFILE =
  "http://ihris.org/fhir/StructureDefinition/hr-training-recommendation-review-profile";

export default {
  name: "TrainingRecommendationView",
  props: ["queries"],

  data() {
    return {
      loading: true,
      error: null,

      recommendation: {},
      response: { nominees: [] },
      review: {},
    };
  },

  computed: {
    backLabel() {
      return (this.queries && this.queries.returnLabel) || "Back";
    },

    sectionMenu() {
      const sections = [
        {
          name: "overview",
          title: "Overview",
          desc: "Course and training details",
        },
        {
          name: "nomination",
          title: "Nomination",
          desc: "Department's nominated staff",
        },
      ];
      if (this.review.id) {
        sections.push({
          name: "review",
          title: "HR Review",
          desc: "Final approval decision",
        });
      }
      return sections;
    },

    // The single, unambiguous status shown in the hero — HR's decision
    // takes precedence once it exists; otherwise fall back to the
    // department response's own (pending) status.
    overallStatusKey() {
      if (this.review.id) return this.reviewStatusKey;
      return this.statusKey(this.response.status);
    },
    overallStatusLabel() {
      if (this.review.id) return this.review.statusDisplay;
      return this.response.statusDisplay || "Pending HR Review";
    },
    reviewStatusKey() {
      return this.statusKey(this.review.status);
    },
  },

  async created() {
    if (!this.queries || !this.queries.responseid) {
      this.error = "No training recommendation response specified.";
      this.loading = false;
      return;
    }

    await this.loadAll();
  },

  methods: {
    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        await this.loadResponse();
        await Promise.all([this.loadRecommendation(), this.loadReview()]);
      } catch (err) {
        console.error("Error loading training recommendation:", err);
        this.error = err.message || "Failed to load recommendation details";
      } finally {
        this.loading = false;
      }
    },

    async loadResponse() {
      const res = await fetch(`/fhir/Basic/${this.queries.responseid}`);
      if (!res.ok) throw new Error("Training recommendation response not found");
      const resource = await res.json();
      if (!resource.meta?.profile?.includes(RESPONSE_PROFILE)) {
        throw new Error("Resource is not a training recommendation response");
      }

      const ext = resource.extension || [];
      const find = (url) => ext.find((e) => e.url === url);

      this.recommendationRef = find(
        "http://ihris.org/fhir/StructureDefinition/training-recommendation-reference",
      )?.valueReference?.reference;

      const statusCoding = find(
        "http://ihris.org/fhir/StructureDefinition/request-status",
      )?.valueCoding;

      const nomineeRefs = ext
        .filter(
          (e) =>
            e.url ===
            "http://ihris.org/fhir/StructureDefinition/ihris-practitioner-reference",
        )
        .map((e) => e.valueReference?.reference)
        .filter(Boolean);

      this.response = {
        id: resource.id,
        departmentDisplay: find(
          "http://ihris.org/fhir/StructureDefinition/department",
        )?.valueCoding?.display,
        status: statusCoding?.code,
        statusDisplay: statusCoding?.display,
        comments: find("http://ihris.org/fhir/StructureDefinition/comments")
          ?.valueString,
        eventDate: find("http://ihris.org/fhir/StructureDefinition/event-date")
          ?.valueDate,
        submittedByRef: find(
          "http://ihris.org/fhir/StructureDefinition/user-reference",
        )?.valueReference?.reference,
        nominees: [],
      };

      await this.loadNominees(nomineeRefs);
      await this.loadSubmittedBy();
    },

    async loadNominees(refs) {
      const myPractitionerRef = this.queries?.practitioner
        ? `Practitioner/${this.queries.practitioner}`
        : null;

      const nominees = await Promise.all(
        refs.map(async (ref) => {
          try {
            const id = ref.split("/")[1];
            const res = await fetch(`/fhir/Practitioner/${id}?_elements=name`);
            if (!res.ok) return { id, name: "Unknown", isMe: ref === myPractitionerRef };
            const practitioner = await res.json();
            const name = practitioner.name?.[0];
            return {
              id,
              name: name
                ? `${name.given?.join(" ") || ""} ${name.family || ""}`.trim()
                : "Unknown",
              isMe: ref === myPractitionerRef,
            };
          } catch (_) {
            return { id: ref, name: "Unknown", isMe: false };
          }
        }),
      );
      this.response.nominees = nominees;
    },

    async loadSubmittedBy() {
      if (!this.response.submittedByRef) return;
      try {
        const id = this.response.submittedByRef.split("/")[1];
        const res = await fetch(`/fhir/Person/${id}?_elements=name`);
        if (!res.ok) return;
        const person = await res.json();
        this.response.submittedByName = person.name?.[0]?.text || "Unknown";
      } catch (_) {
        /* leave blank */
      }
    },

    async loadRecommendation() {
      if (!this.recommendationRef) return;
      try {
        const id = this.recommendationRef.split("/")[1];
        const res = await fetch(`/fhir/Basic/${id}`);
        if (!res.ok) return;
        const resource = await res.json();
        const ext = resource.extension || [];
        const find = (url) => ext.find((e) => e.url === url);

        this.recommendation = {
          id: resource.id,
          title: find("http://ihris.org/fhir/StructureDefinition/ihris-basic-name")
            ?.valueString,
          description: find(
            "http://ihris.org/fhir/StructureDefinition/description",
          )?.valueString,
          course:
            find("http://ihris.org/fhir/StructureDefinition/qualification-name-other")
              ?.valueString ||
            find("http://ihris.org/fhir/StructureDefinition/qualification-name")
              ?.valueReference?.display,
          institution: find(
            "http://ihris.org/fhir/StructureDefinition/planning-institution",
          )?.valueString,
          typeDisplay: find("http://ihris.org/fhir/StructureDefinition/training-type")
            ?.valueCoding?.display,
          qualificationLevel: find(
            "http://ihris.org/fhir/StructureDefinition/qualification-level",
          )?.valueCoding?.display,
          country: find("http://ihris.org/fhir/StructureDefinition/country")
            ?.valueCoding?.display,
          location: find("http://ihris.org/fhir/StructureDefinition/training-location")
            ?.valueString,
          methodology: find(
            "http://ihris.org/fhir/StructureDefinition/learning-methodology",
          )?.valueCoding?.display,
          startDate: find("http://ihris.org/fhir/StructureDefinition/start-date")
            ?.valueDate,
          endDate: find("http://ihris.org/fhir/StructureDefinition/end-date")
            ?.valueDate,
          fiscalYear: find("http://ihris.org/fhir/StructureDefinition/fiscal-year")
            ?.valueString,
          totalParticipants: find(
            "http://ihris.org/fhir/StructureDefinition/total-participants",
          )?.valueInteger,
        };
      } catch (err) {
        console.error("Error loading recommendation:", err);
      }
    },

    async loadReview() {
      try {
        const params = new URLSearchParams({
          _profile: REVIEW_PROFILE,
          trainingrecommendationresponse: `Basic/${this.queries.responseid}`,
          _count: 1,
        });
        const res = await fetch(`/fhir/Basic?${params}`);
        if (!res.ok) return;
        const bundle = await res.json();
        const resource = bundle.entry?.[0]?.resource;
        if (!resource) return;

        const ext = resource.extension || [];
        const find = (url) => ext.find((e) => e.url === url);
        const statusCoding = find(
          "http://ihris.org/fhir/StructureDefinition/review-status",
        )?.valueCoding;

        this.review = {
          id: resource.id,
          status: statusCoding?.code,
          statusDisplay: statusCoding?.display,
          comments: find("http://ihris.org/fhir/StructureDefinition/comments")
            ?.valueString,
          reviewDate: find("http://ihris.org/fhir/StructureDefinition/date")
            ?.valueDate,
          reviewedByRef: find(
            "http://ihris.org/fhir/StructureDefinition/user-reference",
          )?.valueReference?.reference,
        };

        if (this.review.reviewedByRef) {
          const id = this.review.reviewedByRef.split("/")[1];
          const personRes = await fetch(`/fhir/Person/${id}?_elements=name`);
          if (personRes.ok) {
            const person = await personRes.json();
            this.review.reviewedByName = person.name?.[0]?.text || "Unknown";
          }
        }
      } catch (err) {
        console.error("Error loading HR review:", err);
      }
    },

    // ── Display helpers ─────────────────────────────────────────────────
    statusKey(code) {
      const map = {
        approved: "done",
        rejected: "error",
        pending: "warn",
        underreview: "warn",
      };
      return map[code] || "none";
    },

    formatDate(dateString) {
      if (!dateString) return "N/A";
      const date = new Date(dateString);
      return date.toLocaleDateString("en-US", {
        year: "numeric",
        month: "short",
        day: "numeric",
      });
    },

    // ── Navigation ───────────────────────────────────────────────────────
    goBack() {
      if (this.queries && this.queries.returnPath) {
        this.$router.push({
          path: this.queries.returnPath,
          query: this.queries.returnQuery
            ? JSON.parse(this.queries.returnQuery)
            : undefined,
        });
      } else if (window.history.length > 1) {
        this.$router.go(-1);
      } else {
        this.$router.push("/");
      }
    },

    scrollTo(section) {
      const el = document.getElementById(`section-${section}`);
      if (el) el.scrollIntoView({ behavior: "smooth" });
    },
  },
};
</script>

